export const STORAGE_KEY='top-manta-matriu-v1';
export const STAGES=['En estudi','En preparació','Sol·licitada','Concedida','En execució','Pendent de justificar','Justificada','Tancada','Denegada','Desistida','Descartada'];
export const KINDS=['Subvenció','Beca','Conveni','Donació','Altres ingressos'];
export const CATEGORIES=['Personal','Serveis externs','Materials','Desplaçaments','Equipament','Comunicació','Costos indirectes','Altres'];
export const PRIORITIES=['Alta','Mitjana','Baixa'];
export const emptyState=()=>({version:1,projects:[],grants:[],costs:[],allocations:[]});
export const cents=v=>Math.round((v??0)*100);
export const sum=(rows,key)=>rows.reduce((n,r)=>n+cents(r[key]),0)/100;
export const amount=v=>v===null||v===''||v===undefined?null:Math.round(Number(v)*100)/100;
export const alive=g=>!['Denegada','Desistida','Descartada'].includes(g.stage);
export function scope(state,{year='',projectId=''}={}){const matches=r=>(!year||String(r.year)===String(year))&&(!projectId||r.id===projectId);const projects=state.projects.filter(matches);const pids=new Set(projects.map(p=>p.id));const grants=state.grants.filter(g=>(!year||String(g.year)===String(year))&&(!projectId||g.projectId===projectId));const costs=state.costs.filter(c=>pids.has(c.projectId));const gids=new Set(grants.map(g=>g.id)),cids=new Set(costs.map(c=>c.id));const allocations=state.allocations.filter(a=>gids.has(a.grantId)&&cids.has(a.costId));return{...state,projects,grants,costs,allocations};}
export function grantTotals(state,g){const allocations=state.allocations.filter(a=>a.grantId===g.id);return{planned:sum(allocations,'planned'),actual:sum(allocations,'actual'),pending:g.awarded===null?null:(cents(g.awarded)-cents(g.received))/100};}
export function totals(state){const grants=state.grants.filter(alive),planned=sum(state.costs,'planned'),actual=sum(state.costs,'actual'),paid=sum(state.costs,'paid'),awarded=sum(grants,'awarded'),requested=sum(grants,'requested'),received=sum(state.grants,'received'),own=sum(state.projects,'ownPlanned'),other=sum(state.projects,'otherCommitted'),otherCash=sum(state.projects,'ownReceived')+sum(state.projects,'otherReceived');const secured=(cents(awarded)+cents(own)+cents(other))/100;return{planned,actual,paid,requested,awarded,received,own,other,secured,gap:state.projects.reduce((n,p)=>n+Math.max(0,cents(sum(state.costs.filter(c=>c.projectId===p.id),'planned'))-cents(sum(grants.filter(g=>g.projectId===p.id),'awarded'))-cents(p.ownPlanned)-cents(p.otherCommitted)),0)/100,excess:state.projects.reduce((n,p)=>n+Math.max(0,cents(sum(grants.filter(g=>g.projectId===p.id),'awarded'))+cents(p.ownPlanned)+cents(p.otherCommitted)-cents(sum(state.costs.filter(c=>c.projectId===p.id),'planned'))),0)/100,pendingCollection:grants.filter(g=>g.awarded!==null).reduce((n,g)=>n+Math.max(0,cents(g.awarded)-cents(g.received)),0)/100,cashDifference:(cents(received)+cents(otherCash)-cents(paid))/100};}
export function alerts(state,today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date())){const out=[];const push=(level,text,kind,id)=>out.push({level,text,kind,id});for(const g of state.grants){const t=grantTotals(state,g);if(g.received!==null&&g.awarded===null)push('warning',g.name+': hi ha cobraments però falta l’import concedit.','grant',g.id);if(g.awarded!==null&&cents(g.received)>cents(g.awarded))push('danger',g.name+': el cobrat supera el concedit.','grant',g.id);if(!alive(g)&&cents(g.received)>0)push('warning',g.name+': hi ha cobraments en una candidatura denegada o desistida; revisa imports i estat.','grant',g.id);if(['Concedida','En execució','Pendent de justificar','Justificada','Tancada'].includes(g.stage)&&g.awarded===null)push('warning',g.name+': falta l’import concedit.','grant',g.id);const limit=g.awarded??g.requested;if(limit!==null&&cents(t.planned)>cents(limit))push('danger',g.name+': la imputació prevista supera el finançament indicat.','grant',g.id);if(g.awarded!==null&&cents(t.actual)>cents(g.awarded))push('danger',g.name+': la imputació real supera el concedit.','grant',g.id);if(cents(g.maxGrant)>0&&g.requested!==null&&cents(g.requested)>cents(g.maxGrant))push('danger',g.name+': el sol·licitat supera el topall registrat.','grant',g.id);if(g.eligibleBudget!==null&&g.maxRate!==null&&g.requested!==null&&cents(g.requested)>Math.round(cents(g.eligibleBudget)*g.maxRate/100))push('danger',g.name+': el sol·licitat supera la intensitat màxima sobre el pressupost elegible registrat.','grant',g.id);if(!g.projectId&&alive(g))push('warning',g.name+': encara no té projecte assignat.','grant',g.id);if(g.deadline&&g.deadline<today&&['En estudi','En preparació'].includes(g.stage))push('warning',g.name+': el termini de sol·licitud registrat ja ha passat.','grant',g.id);if(g.justification&&g.justification<today&&['Concedida','En execució','Pendent de justificar'].includes(g.stage))push('danger',g.name+': el termini de justificació registrat ja ha passat.','grant',g.id);if(g.start&&g.end&&g.start>g.end)push('danger',g.name+': l’inici d’execució és posterior al final.','grant',g.id);}
for(const c of state.costs){const allocations=state.allocations.filter(a=>a.costId===c.id&&alive(state.grants.find(g=>g.id===a.grantId))),planned=sum(allocations,'planned'),actual=sum(allocations,'actual');if(c.planned!==null&&cents(planned)>cents(c.planned))push('danger',c.label+': la suma imputada prevista supera el cost previst.','cost',c.id);if(c.actual!==null&&cents(actual)>cents(c.actual))push('danger',c.label+': la suma imputada real supera la despesa real registrada.','cost',c.id);if(cents(actual)>0&&c.actual===null)push('warning',c.label+': falta registrar la despesa real per comprovar les imputacions.','cost',c.id);if(c.paid!==null&&c.actual!==null&&cents(c.paid)>cents(c.actual))push('warning',c.label+': el pagat supera la despesa real registrada.','cost',c.id);if(allocations.some(a=>!a.confirmed&&(cents(a.planned)>0||cents(a.actual)>0)))push('warning',c.label+': hi ha imputacions amb elegibilitat pendent de revisar.','cost',c.id);}
for(const p of state.projects){const t=totals(scope(state,{projectId:p.id}));if(t.excess>0&&t.planned>0)push('warning',p.name+': el finançament compromès registrat supera el pressupost previst.','project',p.id);}return out;}
export function blankGrant(year=new Date().getFullYear()){return{id:'',catalogId:'',name:'',organism:'',reference:'',source:'',projectId:'',entity:'',year:Number(year),area:'Barcelona',kind:'Subvenció',stage:'En estudi',priority:'Mitjana',owner:'',requested:null,awarded:null,received:null,eligibleBudget:null,maxRate:null,maxGrant:null,deadline:'',requestDate:'',resolutionDate:'',start:'',end:'',justification:'',nextDate:'',nextAction:'',verified:false,notes:''};}
export function fromCatalog(row,year){return{...blankGrant(year),catalogId:row.id,name:row.name,source:row.source,area:row.area,kind:row.kind==='Beca'?'Beca':'Subvenció',deadline:row.deadline?row.deadline.slice(0,10):'',notes:'Informació del radar (revisió '+row.checked+'). Cal actualitzar-la abans de presentar.\nEntitat potencial: '+row.entity+'\nCondicions: '+row.risk+'\nProposta orientativa: '+row.proposal+'\nImport de referència: '+row.amount};}
const bad=msg=>{throw Error(msg);};
export function validDate(s){return typeof s==='string'&&(s===''||(/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s));}
function textValue(v,name,max=6000){if(typeof v!=='string'||v.length>max)bad('Camp de text no vàlid: '+name);return v;}
function numberValue(v,name,max=1000000000){if(v!==null&&(typeof v!=='number'||!Number.isFinite(v)||v<0||v>max||Math.abs(v*100-Math.round(v*100))>0.0001))bad('Import no vàlid: '+name);return v;}
function idValue(v){textValue(v,'id',150);if(!/^[a-zA-Z0-9_-]+$/.test(v))bad('Identificador no vàlid.');return v;}
function dates(r,keys){for(const k of keys)if(!validDate(r[k]))bad('Data no vàlida: '+k);}
export function validateState(v){if(!v||v.version!==1)bad('Format de còpia no compatible.');const state=emptyState();for(const k of ['projects','grants','costs','allocations'])if(!Array.isArray(v[k])||v[k].length>10000)bad('Llista no vàlida: '+k);
state.projects=v.projects.map(p=>{const r={};r.id=idValue(p.id);for(const k of ['name','entity','owner','notes'])r[k]=textValue(p[k],k);if(!r.name.trim())bad('Falta el nom del projecte.');if(!Number.isInteger(p.year)||p.year<2000||p.year>2100)bad('Any no vàlid.');r.year=p.year;for(const k of ['ownPlanned','ownReceived','otherCommitted','otherReceived'])r[k]=numberValue(p[k],k);return r;});
state.grants=v.grants.map(g=>{const r=blankGrant();r.id=idValue(g.id);for(const k of ['catalogId','name','organism','reference','source','projectId','entity','area','owner','nextAction','notes'])r[k]=textValue(g[k],k);if(!r.name.trim())bad('Falta el nom de la subvenció.');if(r.source&&!/^https?:\/\//i.test(r.source))bad('La font ha de ser un enllaç http o https.');if(!Number.isInteger(g.year)||g.year<2000||g.year>2100)bad('Any no vàlid.');r.year=g.year;for(const [k,options]of [['stage',STAGES],['kind',KINDS],['priority',PRIORITIES]]){if(!options.includes(g[k]))bad('Opció no vàlida: '+k);r[k]=g[k];}for(const k of ['requested','awarded','received','eligibleBudget','maxGrant'])r[k]=numberValue(g[k],k);r.maxRate=numberValue(g.maxRate,'maxRate',100);dates(g,['deadline','requestDate','resolutionDate','start','end','justification','nextDate']);for(const k of ['deadline','requestDate','resolutionDate','start','end','justification','nextDate'])r[k]=g[k];if(typeof g.verified!=='boolean')bad('Validació de requisits no vàlida.');r.verified=g.verified;return r;});
state.costs=v.costs.map(c=>{const r={id:idValue(c.id),projectId:textValue(c.projectId,'projectId'),label:textValue(c.label,'label'),category:c.category,notes:textValue(c.notes,'notes')};if(!r.label.trim()||!CATEGORIES.includes(c.category))bad('Despesa no vàlida.');for(const k of ['planned','actual','paid'])r[k]=numberValue(c[k],k);return r;});
state.allocations=v.allocations.map(a=>{if(typeof a.confirmed!=='boolean')bad('Imputació no vàlida.');return{id:idValue(a.id),grantId:textValue(a.grantId,'grantId'),costId:textValue(a.costId,'costId'),planned:numberValue(a.planned,'planned'),actual:numberValue(a.actual,'actual'),confirmed:a.confirmed};});
for(const key of ['projects','grants','costs','allocations'])if(new Set(state[key].map(r=>r.id)).size!==state[key].length)bad('Hi ha identificadors duplicats.');
const pids=new Set(state.projects.map(p=>p.id)),gmap=new Map(state.grants.map(g=>[g.id,g])),cmap=new Map(state.costs.map(c=>[c.id,c]));
for(const g of state.grants)if(g.projectId&&(!pids.has(g.projectId)||state.projects.find(p=>p.id===g.projectId).year!==g.year))bad('El projecte i l’any de la subvenció no coincideixen.');
for(const c of state.costs)if(!pids.has(c.projectId))bad('Despesa sense projecte vàlid.');
const pairs=new Set();for(const a of state.allocations){const g=gmap.get(a.grantId),c=cmap.get(a.costId);if(!g||!c||!g.projectId||g.projectId!==c.projectId)bad('Imputació amb projecte o registre incorrecte.');const pair=a.grantId+':'+a.costId;if(pairs.has(pair))bad('Imputació duplicada.');pairs.add(pair);}return state;}
export function csvCell(v){let s=String(v??'');if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
const sheet=rows=>'\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n');
export function grantsCSV(state){return sheet([['Id','Convocatòria','Organisme','Referència','Any de gestió','Projecte','Entitat sol·licitant','Tipus','Estat de treball','Prioritat','Responsable','Sol·licitat EUR','Concedit EUR','Cobrat EUR','Pendent de cobrar EUR','Imputació prevista EUR','Imputació real EUR','Pressupost elegible EUR','Intensitat màxima %','Topall EUR','Termini sol·licitud','Data presentada','Resolució','Inici execució','Final execució','Justificació','Acció pendent','Data interna','Requisits revisats','Font','Notes'],...state.grants.map(g=>{const t=grantTotals(state,g);return[g.id,g.name,g.organism,g.reference,g.year,state.projects.find(p=>p.id===g.projectId)?.name??'',g.entity,g.kind,g.stage,g.priority,g.owner,g.requested,g.awarded,g.received,t.pending,t.planned,t.actual,g.eligibleBudget,g.maxRate,g.maxGrant,g.deadline,g.requestDate,g.resolutionDate,g.start,g.end,g.justification,g.nextAction,g.nextDate,g.verified?'Sí':'No',g.source,g.notes];})]);}
export function costsCSV(state){return sheet([['Id','Projecte','Any de gestió','Partida','Despesa','Previst EUR','Real EUR','Pagat EUR','Imputat previst EUR','Imputat real EUR','Notes'],...state.costs.map(c=>{const p=state.projects.find(p=>p.id===c.projectId),a=state.allocations.filter(a=>a.costId===c.id&&alive(state.grants.find(g=>g.id===a.grantId)));return[c.id,p.name,p.year,c.category,c.label,c.planned,c.actual,c.paid,sum(a,'planned'),sum(a,'actual'),c.notes];})]);}
export function allocationsCSV(state){return sheet([['Subvenció','Projecte','Despesa','Partida','Previst EUR','Real EUR','Elegibilitat revisada'],...state.allocations.map(a=>{const g=state.grants.find(g=>g.id===a.grantId),c=state.costs.find(c=>c.id===a.costId);return[g.name,state.projects.find(p=>p.id===c.projectId).name,c.label,c.category,a.planned,a.actual,a.confirmed?'Sí':'No'];})]);}


export function projectsCSV(state){return sheet([['Projecte','Any de gestió','Entitat','Responsable','Pressupost previst EUR','Despesa real EUR','Pagat EUR','Sol·licitat actiu EUR','Subvencions concedides EUR','Subvencions cobrades EUR','Aportació pròpia compromesa EUR','Aportació pròpia disponible EUR','Altres ingressos compromesos EUR','Altres ingressos cobrats EUR','Finançament pendent EUR','Cobraments menys pagaments EUR','Notes'],...state.projects.map(p=>{const t=totals(scope(state,{projectId:p.id}));return[p.name,p.year,p.entity,p.owner,t.planned,t.actual,t.paid,t.requested,t.awarded,t.received,p.ownPlanned,p.ownReceived,p.otherCommitted,p.otherReceived,t.gap,t.cashDifference,p.notes];})]);}
